<script setup lang="ts">
import {ref,watch} from 'vue'
import type {ExperimentTracker} from './experimentTracker'
import {experimentTime,experimentPageLabel} from './experimentRuntime'
import {useDialogAccess} from './dialogAccess'
import {useOverlayHost} from './overlayHost'
const props=defineProps<{tracker:ExperimentTracker;projectId?:string}>(),host=useOverlayHost(),name=ref(''),runs=ref<any[]>([]),standaloneNotes=ref<any[]>([]),report=ref<any>(null),timeline=ref<any[]>([]),outputs=ref<any[]>([]),versions=ref<any[]>([]),error=ref(''),busy=ref(false),selected=ref(''),page=ref(''),kind=ref(''),offset=ref(0),total=ref(0)
const dialog=ref<HTMLElement>(),keyboard=useDialogAccess(()=>props.tracker.state.panel,dialog)
async function downloadLocal(){const records=await props.tracker.localRecords();const url=URL.createObjectURL(new Blob([JSON.stringify(records,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='experiment-pending-records.json';a.click();URL.revokeObjectURL(url)}
const labels:Record<string,string>={click:'点击',input_change:'输入／修改',agent_submit:'智能修改指令',api_request:'操作请求',api_response:'操作结果',server_action:'已保存的变更',navigation:'进入模块',dwell:'前台停留',media_play:'开始播放',media_pause:'暂停播放',media_ended:'播放结束',media_open:'进入分镜',character_focus:'选择人物',end_unsaved_changes:'结束时未保存修改'}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function loadEvents(){if(!selected.value)return;const result=await props.tracker.request(`/experiments/${selected.value}/events?offset=${offset.value}&limit=100&page=${encodeURIComponent(page.value)}&kind=${encodeURIComponent(kind.value)}`);timeline.value=result.events;total.value=result.total}
async function choose(id:string){selected.value=id;offset.value=0;outputs.value=[];versions.value=[];report.value=await props.tracker.request('/experiments/'+id);await loadEvents()}
async function refresh(){standaloneNotes.value=(await props.tracker.request('/experiment-notes'+(props.projectId?'?projectId='+encodeURIComponent(props.projectId):''))).filter((note:any)=>!note.runId);runs.value=await props.tracker.request('/experiments');const id=selected.value||props.tracker.state.run?.id||runs.value[0]?.id;if(id)await choose(id)}
async function begin(){await props.tracker.start(name.value);selected.value=props.tracker.state.run.id;await refresh()}
async function end(){await props.tracker.stop();selected.value=props.tracker.state.run.id;await refresh()}
function details(event:any){return JSON.stringify(event.data,null,2)}
watch(()=>props.tracker.state.panel,open=>{if(open)void run(refresh)})
watch([page,kind],()=>{offset.value=0;void run(loadEvents)})
</script>
<template><Teleport :to="host"><div v-if="tracker.state.panel" class="experiment-backdrop" data-experiment-ignore @click.self="tracker.state.panel=false"><section ref="dialog" class="experiment-panel" @keydown="keyboard" role="dialog" aria-modal="true" aria-labelledby="experiment-title" tabindex="-1" @keydown.esc.stop.prevent="tracker.state.panel=false"><header><div><small>RESEARCH SESSION</small><h2 id="experiment-title">实验记录</h2></div><button class="icon-button" aria-label="关闭实验面板" @click="tracker.state.panel=false">×</button></header>
 <div class="experiment-body"><section class="experiment-controls"><template v-if="!tracker.recording()&&!tracker.state.stopping"><label>实验名称／参与者编号（可选）<input v-model="name" placeholder="例如 P01 · 资料整理任务" maxlength="160"></label><button class="primary" :disabled="busy||tracker.state.loading" @click="run(begin)">开始实验</button></template><template v-else><div><b>{{tracker.state.run.name}}</b><p class="experiment-live"><i/>{{tracker.state.stopping?'已停止采集，等待结束同步':'实验进行中'}} · {{experimentTime(tracker.state.elapsedMs)}}</p></div><button class="experiment-end" :disabled="busy||tracker.state.loading" @click="run(end)">{{tracker.state.stopping?'重试结束并同步':'结束实验'}}</button></template><p class="experiment-description">开始后记录本站各模块的前台停留、操作顺序、输入修改、智能修改指令及产出。密码不记录；截图由你手动框选，仅保存选区。切换页面和项目不会结束实验。</p><button v-if="tracker.state.pending" @click="run(downloadLocal)">导出本机待同步记录</button><p class="experiment-sync">{{tracker.state.pending?tracker.state.pending+' 条待同步记录':'操作记录已同步'}}<span v-if="tracker.state.issue"> · {{tracker.state.issue}}</span></p></section>
 <p v-if="error" role="alert" class="extension-error">{{error}}</p>
 <div class="experiment-toolbar"><label>查看实验<select :value="selected" @change="run(()=>choose(($event.target as HTMLSelectElement).value))"><option v-for="r in runs" :key="r.id" :value="r.id">{{r.name}} · {{r.status==='running'?'进行中':'已结束'}} · {{new Date(r.startedAt).toLocaleString()}}</option></select></label><button :disabled="busy" @click="run(refresh)">刷新统计</button><template v-if="selected"><a :href="`/api/experiments/${selected}/export?format=zip`" download>导出 ZIP</a><a :href="`/api/experiments/${selected}/export?format=csv`" download>CSV</a><a :href="`/api/experiments/${selected}/export?format=json`" download>JSON</a></template></div>
 <template v-if="report"><div class="experiment-metrics"><div><small>总时长</small><b>{{experimentTime(report.durationMs)}}</b></div><div><small>前台时长</small><b>{{experimentTime(report.foregroundMs)}}</b></div><div><small>产出变更</small><b>{{report.outputs.length}}</b></div><div><small>事件记录</small><b>{{report.eventCount}}</b></div><div><small>截图与便笺</small><b>{{report.notes.length}}</b></div></div><p class="experiment-description">总时长从开始到结束；前台时长仅统计页面可见且窗口有焦点的时间。停留时间不是持续操作时间。</p>
 <h3>模块互动</h3><table class="experiment-table"><thead><tr><th>模块</th><th>前台停留</th><th>进入次数</th><th>点击</th><th>输入修改</th><th>智能修改</th><th>操作／分钟</th></tr></thead><tbody><tr v-for="m in report.modules" :key="m.page"><td>{{m.label}}</td><td>{{experimentTime(m.foregroundMs)}}</td><td>{{m.visits}}</td><td>{{m.clicks}}</td><td>{{m.inputs}}</td><td>{{m.agentMessages}}</td><td>{{m.actionsPerMinute??'—'}}</td></tr></tbody></table>
 <h3>访问顺序</h3><div class="experiment-order"><span v-for="(step,i) in report.order" :key="i"><small>{{experimentTime(step.elapsedMs)}}</small>{{step.label}}<b v-if="Number(i)<report.order.length-1">→</b></span></div>
 <details class="experiment-section"><summary>产出的内容（{{report.outputs.length}} 项）</summary><button @click="run(async()=>{outputs=await tracker.request(`/experiments/${selected}/outputs`);versions=await tracker.request(`/experiments/${selected}/versions`)})">读取前后内容</button><article v-for="output in outputs" :key="output.projectId+output.key"><details><summary>{{output.name}} · {{output.kind}} · {{output.change==='created'?'新增':output.change==='removed'?'移除':'修改'}}</summary><div class="output-comparison"><div><b>实验前</b><pre>{{JSON.stringify(output.before?.draft||null,null,2)}}</pre></div><div><b>实验后</b><pre>{{JSON.stringify(output.after?.draft||null,null,2)}}</pre></div></div></details></article><details v-if="versions.length"><summary>中间保存版本（当前显示 {{versions.length}} / {{report.versionCount}}） · 包含被覆盖或删除的内容</summary><article v-for="version in versions" :key="version.eventId"><details><summary>{{experimentTime(version.elapsedMs)}} · {{version.action}}</summary><pre>{{JSON.stringify(version.content,null,2)}}</pre></details></article></details><p class="experiment-description">共 {{report.versionCount}} 个保存版本。</p><p v-if="!outputs.length" class="experiment-description">点击读取前后内容；完整数据也包含在 JSON／ZIP 导出中。</p></details>
 <details class="experiment-section" open><summary>截图与便笺（{{report.notes.length}}）</summary><div class="experiment-notes"><article v-for="note in report.notes" :key="note.id"><a v-if="note.imageUrl" :href="note.imageUrl" target="_blank"><img :src="note.imageUrl" alt="用户框选的反馈截图"></a><small>{{experimentPageLabel(note.page)}} · {{note.elapsedMs===null?'实验外':experimentTime(note.elapsedMs)}} · {{note.category==='bug'?'问题':note.category==='discomfort'?'体验不适':note.category==='idea'?'想法':'文字反馈'}}</small><p>{{note.text}}</p></article></div></details>
 <details class="experiment-section"><summary>操作时间线</summary><div class="experiment-toolbar"><label>模块<select v-model="page"><option value="">全部模块</option><option v-for="m in report.modules" :value="m.page">{{m.label}}</option></select></label><label>事件<select v-model="kind"><option value="">全部事件</option><option value="input_change">输入修改</option><option value="agent_submit">智能修改指令</option><option value="click">按钮点击</option><option value="server_action">已保存的变更</option></select></label><button :disabled="offset===0" @click="offset=Math.max(0,offset-100);run(loadEvents)">上一页</button><small>{{offset+1}}–{{Math.min(offset+100,total)}} / {{total}}</small><button :disabled="offset+100>=total" @click="offset+=100;run(loadEvents)">下一页</button></div><article v-for="event in timeline" :key="event.id" class="experiment-event"><small>{{experimentTime(event.elapsedMs)}} · {{experimentPageLabel(event.page)}} · {{labels[event.kind]||event.kind}}</small><b>{{event.data.label||event.data.path||event.data.action||''}}</b><details><summary>查看输入与操作详情</summary><pre>{{details(event)}}</pre></details></article></details>
 </template><p v-else class="experiment-description">点击开始实验后，统计会持续到结束；浮动截图按钮随时可用。</p><details v-if="standaloneNotes.length" class="experiment-section"><summary>实验外的独立便笺（{{standaloneNotes.length}}）</summary><div class="experiment-notes"><article v-for="note in standaloneNotes" :key="note.id"><a v-if="note.imageUrl" :href="note.imageUrl" target="_blank"><img :src="note.imageUrl" alt="用户框选的反馈截图"></a><small>{{experimentPageLabel(note.page)}} · {{new Date(note.createdAt).toLocaleString()}}</small><p>{{note.text}}</p></article></div></details></div>
 </section></div></Teleport></template>
<style scoped>.experiment-backdrop{position:fixed;inset:0;background:#142d2840;z-index:140;display:flex;justify-content:flex-end}.experiment-panel{width:min(1120px,86vw);height:100dvh;background:#fcfdf8;box-shadow:-12px 0 60px #163b2629;color:#45604a;display:flex;flex-direction:column}.experiment-panel>header{display:flex;align-items:center;justify-content:space-between;padding:24px 30px;border-bottom:1px solid #e0e8d9}.experiment-panel header small{font-size:9px;letter-spacing:.14em;color:#98a68b}.experiment-panel h2{margin:5px 0;font-size:22px}.experiment-body{overflow:auto;padding:24px 30px;flex:1}.experiment-controls{padding:20px;border-radius:12px;border:1px solid #d4e1c9;background:#f3f7ec;display:flex;align-items:center;gap:18px;flex-wrap:wrap}.experiment-controls label{flex:1;margin:0;min-width:260px;font-size:12px}.experiment-controls input{margin-top:7px}.experiment-description,.experiment-sync{font-size:11px;line-height:1.8;color:#8b9981;width:100%;margin:8px 0}.experiment-sync{color:#738b64}.experiment-live{font-size:12px}.experiment-live i{display:inline-block;width:7px;height:7px;background:#ad6557;border-radius:100%;margin-right:7px}.experiment-end{border-color:#c79f91;color:#976956;background:#fff8f3}.experiment-toolbar{display:flex;gap:12px;align-items:end;margin:20px 0;flex-wrap:wrap}.experiment-toolbar label{font-size:11px;min-width:140px;margin:0}.experiment-toolbar select{margin-top:6px}.experiment-toolbar button,.experiment-toolbar a{font-size:11px;white-space:nowrap}.experiment-toolbar a{color:#668d6b}.experiment-metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-top:24px}.experiment-metrics>div{padding:17px 14px;background:#fffef7;border:1px solid #e0e6d8;border-radius:9px}.experiment-metrics small{display:block;font-size:10px;color:#8c9982;margin-bottom:8px}.experiment-metrics b{font-size:20px;font-weight:500}.experiment-body h3{font-size:13px;margin:25px 0 12px}.experiment-table{width:100%;font-size:11px;border-collapse:collapse}.experiment-table th,.experiment-table td{padding:11px 8px;text-align:left;border-bottom:1px solid #e6ecdf}.experiment-table th{color:#91a083;font-weight:400}.experiment-order{display:flex;flex-wrap:wrap;gap:12px;font-size:11px}.experiment-order span{display:flex;align-items:center;gap:7px}.experiment-order small{color:#98a58b}.experiment-order b{font-weight:400;color:#a9b09e}.experiment-section{border-top:1px solid #dde6d5;padding-top:18px;margin-top:24px}.experiment-section>summary{font-size:13px;cursor:pointer;margin-bottom:15px}.experiment-section article{padding:12px 0}.experiment-section pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:420px;overflow:auto;font-size:11px;line-height:1.7;background:#f2f5ec;padding:12px}.output-comparison{display:grid;grid-template-columns:1fr 1fr;gap:14px;min-width:0}.output-comparison>div{min-width:0;font-size:12px}.experiment-notes{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.experiment-notes img{width:100%;height:150px;object-fit:contain;background:#eff2e9;border:1px solid #e0e6d9;border-radius:7px}.experiment-notes small,.experiment-event small{display:block;color:#96a18a;font-size:10px;margin:8px 0}.experiment-notes p{font-size:12px;line-height:1.8;white-space:pre-wrap}.experiment-event b{font-size:12px;font-weight:500}.experiment-event summary{font-size:10px;color:#91a184;margin-top:8px}</style>
